<script>
(function () {
    'use strict';

    var sidebarNav = document.querySelector('.sidebar .nav');
    var activeLink = sidebarNav ? sidebarNav.querySelector('a.active') : null;

    if (!sidebarNav || !activeLink || window.matchMedia('(max-width: 760px)').matches) {
        return;
    }

    window.requestAnimationFrame(function () {
        var navRect = sidebarNav.getBoundingClientRect();
        var linkRect = activeLink.getBoundingClientRect();

        if (linkRect.top < navRect.top || linkRect.bottom > navRect.bottom) {
            activeLink.scrollIntoView({ block: 'center', behavior: 'auto' });
        }
    });
})();
</script>
